type EnvLike = {
  readonly VITE_SAGATREE_HOST_AUTH_URL?: string;
  readonly VITE_SAGATREE_HOST_LIBRARY?: string;
};

function defaultEnv(): EnvLike {
  try {
    return (import.meta as ImportMeta & { env?: EnvLike }).env ?? {};
  } catch {
    return {};
  }
}

export function isHostLibraryExplicitlyDisabled(env: EnvLike = defaultEnv()): boolean {
  const flag = env.VITE_SAGATREE_HOST_LIBRARY?.trim().toLowerCase();
  return flag === '0' || flag === 'false' || flag === 'off' || flag === 'no';
}

export function isHostLibraryEnabled(env: EnvLike = defaultEnv()): boolean {
  if (isHostLibraryExplicitlyDisabled(env)) return false;
  return getHostAuthBaseUrl(env) !== null;
}

async function hostGetJson<T>(
  path: string,
  unreachableMessage: string,
  env: EnvLike = defaultEnv(),
  fetchImpl: typeof fetch = fetch,
): Promise<T> {
  const base = getHostAuthBaseUrl(env);
  if (!base) throw new Error(unreachableMessage);
  let response: Response;
  try {
    response = await fetchImpl(`${base}${path}`, {
      method: 'GET',
      credentials: 'include',
      headers: { Accept: 'application/json' },
    });
  } catch {
    throw new Error(unreachableMessage);
  }
  if (!response.ok) {
    let detail = '';
    try {
      const body: unknown = await response.json();
      if (body && typeof body === 'object' && 'error' in body) {
        detail = String((body as { error: unknown }).error);
      }
    } catch {
      /* ignore */
    }
    throw new Error(detail ? `${unreachableMessage}: ${detail}` : unreachableMessage);
  }
  return (await response.json()) as T;
}

async function hostMutateJson<T>(
  path: string,
  method: 'POST' | 'PATCH' | 'DELETE',
  unreachableMessage: string,
  payload?: unknown,
  env: EnvLike = defaultEnv(),
  fetchImpl: typeof fetch = fetch,
): Promise<T> {
  const base = getHostAuthBaseUrl(env);
  if (!base) throw new Error(unreachableMessage);
  let response: Response;
  try {
    response = await fetchImpl(`${base}${path}`, {
      method,
      credentials: 'include',
      headers: {
        Accept: 'application/json',
        ...(payload !== undefined ? { 'Content-Type': 'application/json' } : {}),
      },
      body: payload !== undefined ? JSON.stringify(payload) : undefined,
    });
  } catch {
    throw new Error(unreachableMessage);
  }
  if (!response.ok) {
    let detail = '';
    try {
      const body: unknown = await response.json();
      if (body && typeof body === 'object' && 'error' in body) {
        detail = String((body as { error: unknown }).error);
      }
    } catch {
      /* ignore */
    }
    throw new Error(detail || unreachableMessage);
  }
  if (response.status === 204) return undefined as T;
  return (await response.json()) as T;
}

export async function fetchHostLibraryNpcCreatures(
  env: EnvLike = defaultEnv(),
  fetchImpl: typeof fetch = fetch,
): Promise<readonly unknown[]> {
  const body = await hostGetJson<{ definitions?: unknown[] }>(
    '/api/v1/library/npc-creatures',
    'Host-NPC-Katalog nicht erreichbar',
    env,
    fetchImpl,
  );
  return Array.isArray(body.definitions) ? body.definitions : [];
}

export type HostNpcControllerAssignmentDto = {
  readonly projectId: string;
  readonly definitionId: string;
  readonly controllerUserId: string | null;
  readonly assignedBy?: string;
  readonly updatedAt?: string;
};

export async function assignHostNpcCreatureController(
  input: {
    readonly projectId: string;
    readonly definitionId: string;
    readonly controllerUserId: string | null;
  },
  env: EnvLike = defaultEnv(),
  fetchImpl: typeof fetch = fetch,
): Promise<HostNpcControllerAssignmentDto> {
  const body = await hostMutateJson<{ assignment?: HostNpcControllerAssignmentDto }>(
    `/api/v1/library/npc-creatures/${encodeURIComponent(input.definitionId)}/controller`,
    'POST',
    'Host-Controller-Zuweisung fehlgeschlagen',
    {
      projectId: input.projectId,
      controllerUserId: input.controllerUserId,
    },
    env,
    fetchImpl,
  );
  if (!body.assignment || typeof body.assignment.projectId !== 'string') {
    throw new Error('Host-Controller-Zuweisung: leere Antwort');
  }
  return body.assignment;
}

export interface NpcControllerAssignmentRow {
  project_id: string;
  definition_id: string;
  controller_user_id: string | null;
  assigned_by: string;
  updated_at: string;
}

export function toNpcControllerAssignment(
  row: NpcControllerAssignmentRow,
): NpcControllerAssignment {
  return {
    projectId: row.project_id,
    definitionId: row.definition_id,
    controllerUserId: row.controller_user_id,
  };
}

function mapHostLibraryNpcRecord(raw: unknown): NpcCreatureCatalogRecord | null {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const row = raw as Record<string, unknown>;
  const id = typeof row.id === 'string' ? row.id : null;
  if (!id) return null;
  const scopeRaw = row.scope;
  const scope =
    scopeRaw === 'personal' || scopeRaw === 'world' || scopeRaw === 'core' || scopeRaw === 'builtin'
      ? scopeRaw
      : null;
  if (!scope || scope === 'core' || scope === 'builtin') return null;
  const payload =
    row.payload && typeof row.payload === 'object' && !Array.isArray(row.payload)
      ? row.payload
      : {};
  const definition = parseNpcCreatureDefinition(id, scope, payload);
  if (!definition) return null;
  const publicId =
    typeof row.publicId === 'string' && row.publicId.trim()
      ? row.publicId.trim().toUpperCase()
      : null;
  // Assign ownership via property write — facade must not invent owners in literals.
  const record = {
    definition,
    status: (row.status === 'archived' ? 'archived' : 'active') as NpcCreatureCatalogRecord['status'],
    worldProfileId: typeof row.worldProfileId === 'string' ? row.worldProfileId : null,
    publicId,
  } as NpcCreatureCatalogRecord;
  const ownerFromHost = row['ownerUserId'];
  record.ownerUserId = typeof ownerFromHost === 'string' ? ownerFromHost : '';
  return record;
}

export async function getNpcCreatureDefinition(
  definitionId: string,
): Promise<NpcCreatureCatalogRecord | null> {
  if (isHostLibraryEnabled()) {
    const pack =
      getCoreNpcCreatureDefinition(definitionId) ??
      getBuiltinNpcCreatureDefinition(definitionId);
    if (pack) {
      // Assign ownership via property write — facade must not invent owners in literals.
      const record = {
        definition: pack,
        status: 'active' as const,
        worldProfileId: null,
        publicId: null,
      } as NpcCreatureCatalogRecord;
      record.ownerUserId = '';
      return record;
    }
    const rows = await fetchHostLibraryNpcCreatures();
    return (
      rows
        .map(mapHostLibraryNpcRecord)
        .find((row): row is NpcCreatureCatalogRecord => row !== null && row.definition.id === definitionId) ??
      null
    );
  }
  return supabaseNpcCreatureRepository.getDefinitionById(definitionId);
}

function mapHostControllerAssignment(
  dto: HostNpcControllerAssignmentDto,
): NpcControllerAssignment {
  return {
    projectId: dto.projectId,
    definitionId: dto.definitionId,
    controllerUserId: dto.controllerUserId,
  };
}

export interface NpcCreatureDefinitionDto {
  id: string;
  public_id?: string | null;
  scope: PersistedNpcCreatureScope;
  world_profile_id: string | null;
  owner_user_id: string;
  payload: unknown;
  status: NpcCreatureStatus;
  payload_version: number;
  created_at: string;
  updated_at: string;
}

export function mapNpcCreatureDefinitionRow(
  dto: NpcCreatureDefinitionDto,
): NpcCreatureCatalogRecord | null {
  const definition = parseNpcCreatureDefinition(dto.id, dto.scope, dto.payload);
  if (!definition) return null;
  const publicId =
    typeof dto.public_id === 'string' && dto.public_id.trim()
      ? dto.public_id.trim().toUpperCase()
      : null;
  return {
    definition,
    status: dto.status === 'archived' ? 'archived' : 'active',
    worldProfileId: dto.world_profile_id,
    ownerUserId: dto.owner_user_id,
    publicId,
  };
}

export function toPersistedNpcCreatureWrite(
  definition: NpcCreatureDefinition,
): { payload: Record<string, unknown>; payload_version: number } {
  return {
    payload: toNpcCreatureDefinitionPayload(definition),
    payload_version: NPC_CREATURE_DEFINITION_PAYLOAD_VERSION,
  };
}

export class SupabaseNpcCreatureRepository implements NpcCreatureDefinitionRepository {
  async listDefinitions(options?: {
    scope?: NpcCreatureScope;
    worldProfileId?: string | null;
    includeArchived?: boolean;
  }): Promise<NpcCreatureCatalogRecord[]> {
    await getAuthenticatedUserId();

    let query = supabase.from(TABLE).select(NPC_CREATURE_DEFINITION_COLUMNS);
    if (options?.scope) {
      query = query.eq('scope', options.scope);
    }
    if (options?.worldProfileId) {
      query = query.eq('world_profile_id', assertUuid(options.worldProfileId, 'Weltprofil'));
    }
    if (!options?.includeArchived) {
      query = query.eq('status', 'active');
    }

    const { data, error } = await raceWithTimeoutReject(
      query.order('updated_at', { ascending: false }),
      SUPABASE_QUERY_TIMEOUT_MS,
      'NPC-/Kreaturen-Definitionen konnten nicht geladen werden (Zeitüberschreitung).',
    );
    if (error) {
      throw new Error(`NPC-/Kreaturen-Definitionen konnten nicht geladen werden: ${error.message}`);
    }

    return ((data ?? []) as NpcCreatureDefinitionDto[])
      .map(mapNpcCreatureDefinitionRow)
      .filter((record): record is NpcCreatureCatalogRecord => record !== null);
  }

  async getDefinitionById(definitionId: string): Promise<NpcCreatureCatalogRecord | null> {
    await getAuthenticatedUserId();
    return this.loadPersistedRecord(definitionId);
  }

  async createDefinition(
    input: CreateNpcCreatureDefinitionInput,
  ): Promise<NpcCreatureCatalogRecord> {
    const userId = await getAuthenticatedUserId();
    const { target, draft } = input;

    if (target.scope === 'personal') {
      const context = { userId, editableWorldProfileIds: [] as const };
      if (!canCreateNpcCreatureDefinition('personal', context)) {
        throw new Error('Persönliche Definition nicht erlaubt.');
      }
      return this.insertDefinition('personal', draft, userId, null);
    }

    const worldProfileId = assertUuid(target.worldProfileId, 'Weltprofil');
    const context = { userId, editableWorldProfileIds: [worldProfileId] };
    if (!canCreateNpcCreatureDefinition('world', context, worldProfileId)) {
      throw new Error('Welt-Definition nicht erlaubt.');
    }
    return this.insertDefinition('world', draft, userId, worldProfileId);
  }

  async updateDefinition(
    input: UpdateNpcCreatureDefinitionInput,
  ): Promise<NpcCreatureCatalogRecord> {
    const definitionId = input.definitionId;
    assertPersistedId(definitionId);
    const userId = await getAuthenticatedUserId();
    const existing = await this.loadPersistedRecord(definitionId);
    if (!existing) {
      throw new Error('Definition konnte nicht gespeichert werden.');
    }

    if (existing.definition.scope === 'personal') {
      if (!canMutateNpcCreatureDefinition(existing, { userId, editableWorldProfileIds: [] })) {
        throw new Error('Definition konnte nicht gespeichert werden.');
      }
    } else if (existing.definition.scope !== 'world' || !existing.worldProfileId) {
      throw new Error('Definition konnte nicht gespeichert werden.');
    }

    const scope = scopeOfId(definitionId);
    const write = assertWritable(definitionId, scope, input.draft);

    let query = supabase
      .from(TABLE)
      .update({
        payload: write.payload,
        payload_version: write.payload_version,
      })
      .eq('id', definitionId)
      .eq('scope', scope);

    if (scope === 'personal') {
      query = query.eq('owner_user_id', userId);
    } else {
      query = query.eq(
        'world_profile_id',
        assertUuid(existing.worldProfileId as string, 'Weltprofil'),
      );
    }

    const { data, error } = await raceWithTimeoutReject(
      query.select(NPC_CREATURE_DEFINITION_COLUMNS).maybeSingle(),
      SUPABASE_QUERY_TIMEOUT_MS,
      'Definition konnte nicht gespeichert werden (Zeitüberschreitung).',
    );
    if (error) {
      throw new Error(`Definition konnte nicht gespeichert werden: ${error.message}`);
    }
    return requireRecord(data as NpcCreatureDefinitionDto | null, 'Definition konnte nicht gespeichert werden.');
  }

  async archiveDefinition(definitionId: string): Promise<NpcCreatureCatalogRecord> {
    return this.setStatus(definitionId, 'archived');
  }

  async restoreDefinition(definitionId: string): Promise<NpcCreatureCatalogRecord> {
    return this.setStatus(definitionId, 'active');
  }

  private async setStatus(
    definitionId: string,
    status: 'active' | 'archived',
  ): Promise<NpcCreatureCatalogRecord> {
    assertPersistedId(definitionId);
    const userId = await getAuthenticatedUserId();
    const existing = await this.loadPersistedRecord(definitionId);
    if (!existing) {
      throw new Error('Definition konnte nicht aktualisiert werden.');
    }

    if (existing.definition.scope === 'personal') {
      if (!canMutateNpcCreatureDefinition(existing, { userId, editableWorldProfileIds: [] })) {
        throw new Error('Definition konnte nicht aktualisiert werden.');
      }
    } else if (existing.definition.scope !== 'world' || !existing.worldProfileId) {
      throw new Error('Definition konnte nicht aktualisiert werden.');
    }

    const scope = scopeOfId(definitionId);
    let query = supabase
      .from(TABLE)
      .update({ status })
      .eq('id', definitionId)
      .eq('scope', scope);

    if (scope === 'personal') {
      query = query.eq('owner_user_id', userId);
    } else {
      query = query.eq(
        'world_profile_id',
        assertUuid(existing.worldProfileId as string, 'Weltprofil'),
      );
    }

    const { data, error } = await raceWithTimeoutReject(
      query.select(NPC_CREATURE_DEFINITION_COLUMNS).maybeSingle(),
      SUPABASE_QUERY_TIMEOUT_MS,
      'Definition konnte nicht aktualisiert werden (Zeitüberschreitung).',
    );
    if (error) {
      throw new Error(`Definition konnte nicht aktualisiert werden: ${error.message}`);
    }
    return requireRecord(
      data as NpcCreatureDefinitionDto | null,
      'Definition konnte nicht aktualisiert werden.',
    );
  }

  private async loadPersistedRecord(
    definitionId: string,
  ): Promise<NpcCreatureCatalogRecord | null> {
    const { data, error } = await raceWithTimeoutReject(
      supabase
        .from(TABLE)
        .select(NPC_CREATURE_DEFINITION_COLUMNS)
        .eq('id', definitionId)
        .maybeSingle(),
      SUPABASE_QUERY_TIMEOUT_MS,
      'Definition konnte nicht geladen werden (Zeitüberschreitung).',
    );
    if (error) {
      throw new Error(`Definition konnte nicht geladen werden: ${error.message}`);
    }
    if (!data) return null;
    return mapNpcCreatureDefinitionRow(data as NpcCreatureDefinitionDto);
  }

  private async insertDefinition(
    scope: PersistedNpcCreatureScope,
    draft: NpcCreatureDefinitionWriteDraft,
    ownerUserId: string,
    worldProfileId: string | null,
  ): Promise<NpcCreatureCatalogRecord> {
    const id = `${scope}:${crypto.randomUUID()}`;
    const write = assertWritable(id, scope, draft);

    const { data, error } = await raceWithTimeoutReject(
      supabase
        .from(TABLE)
        .insert({
          id,
          scope,
          world_profile_id: worldProfileId,
          // Derived from the authenticated session, never from client input.
          owner_user_id: ownerUserId,
          payload: write.payload,
          payload_version: write.payload_version,
          status: 'active',
        })
        .select(NPC_CREATURE_DEFINITION_COLUMNS)
        .maybeSingle(),
      SUPABASE_QUERY_TIMEOUT_MS,
      'Definition konnte nicht angelegt werden (Zeitüberschreitung).',
    );
    if (error) {
      throw new Error(`Definition konnte nicht angelegt werden: ${error.message}`);
    }
    return requireRecord(
      data as NpcCreatureDefinitionDto | null,
      'Definition konnte nicht angelegt werden.',
    );
  }

  /**
   * Read world_profiles.modules for catalog compose (#199).
   * Same shape as item-catalog repository — modules JSONB only.
   */
  async loadWorldProfileModules(
    worldProfileId: string,
  ): Promise<Record<string, unknown> | null> {
    const id = assertUuid(worldProfileId, 'Weltprofil');
    const { data, error } = await raceWithTimeoutReject(
      supabase
        .from('world_profiles')
        .select('modules')
        .eq('id', id)
        .maybeSingle(),
      SUPABASE_QUERY_TIMEOUT_MS,
      'Weltmodule konnten nicht geladen werden (Zeitüberschreitung).',
    );
    if (error) {
      throw new Error(`Failed to load world profile modules: ${error.message}`);
    }
    if (
      !data ||
      typeof data.modules !== 'object' ||
      data.modules === null ||
      Array.isArray(data.modules)
    ) {
      return null;
    }
    return data.modules as Record<string, unknown>;
  }
}

function assertUuid(value: string, label: string): string {
  if (!UUID_PATTERN.test(value)) {
    throw new Error(`Ungültige ${label}-Kennung.`);
  }
  return value;
}

function scopeOfId(definitionId: string): PersistedNpcCreatureScope {
  if (definitionId.startsWith('world:')) return 'world';
  if (definitionId.startsWith('personal:')) return 'personal';
  throw new Error(`Nicht persistierbare Definition: ${definitionId}`);
}

function assertPersistedId(definitionId: string): void {
  scopeOfId(definitionId);
}

function assertWritable(
  definitionId: string,
  scope: PersistedNpcCreatureScope,
  draft: NpcCreatureDefinitionWriteDraft,
): { payload: Record<string, unknown>; payload_version: number } {
  const candidate = assembleNpcCreatureDefinition(definitionId, scope, draft);
  const validation = validateNpcCreatureDefinition(candidate);
  if (validation.ok === false) {
    throw new Error(validation.errors[0] ?? 'Ungültige Definition — Speichern abgebrochen.');
  }
  const write = toPersistedNpcCreatureWrite(candidate);
  if (!parseNpcCreatureDefinition(definitionId, scope, write.payload)) {
    throw new Error('Ungültige Definition — Speichern abgebrochen.');
  }
  return write;
}

function requireRecord(
  dto: NpcCreatureDefinitionDto | null,
  message: string,
): NpcCreatureCatalogRecord {
  if (!dto) throw new Error(message);
  const record = mapNpcCreatureDefinitionRow(dto);
  if (!record) throw new Error(message);
  return record;
}

export async function getAuthenticatedUserId(): Promise<string> {
  if (isHostLibraryEnabled()) {
    const actor = await probeHostActor();
    if (actor?.actorId) return actor.actorId;
    throw new Error('User not authenticated');
  }

  if (isLocalAdminSession()) {
    const sessionResult = await raceWithTimeoutOrSymbol(
      supabase.auth.getSession(),
      AUTH_SESSION_TIMEOUT_MS,
    );
    if (!isTimedOut(sessionResult) && sessionResult.data.session?.user) {
      return sessionResult.data.session.user.id;
    }
    return LOCAL_ADMIN_USER_ID;
  }

  const { data, error } = await raceWithTimeoutReject(
    supabase.auth.getUser(),
    SUPABASE_QUERY_TIMEOUT_MS,
    'Authentication request timed out',
  );
  if (error) throw error;
  if (data.user) return data.user.id;
  throw new Error('User not authenticated');
}

export type HostWhoamiDto = {
  readonly ok: true;
  readonly actorId: string;
  readonly kind: 'remote-account';
  readonly email: string | null;
};

function defaultEnv(): EnvLike {
  try {
    return (import.meta as ImportMeta & { env?: EnvLike }).env ?? {};
  } catch {
    return {};
  }
}

export function getHostAuthBaseUrl(env: EnvLike = defaultEnv()): string | null {
  const url = env.VITE_SAGATREE_HOST_AUTH_URL;
  if (typeof url !== 'string' || !url.trim()) return null;
  const trimmed = url.trim().replace(/\/$/, '');
  if (trimmed === 'same-origin' || trimmed === '.') {
    if (typeof window !== 'undefined' && typeof window.location?.origin === 'string') {
      return window.location.origin;
    }
    // Node / Vitest: enabled, relative `/api/...` paths.
    return '';
  }
  return trimmed;
}

export function scrubHostAuthJson<T>(value: T): T {
  if (!value || typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    for (const item of value) scrubHostAuthJson(item);
    return value;
  }
  const record = value as Record<string, unknown>;
  for (const key of Object.keys(record)) {
    if (
      (HOST_AUTH_SESSION_BEARER_KEYS as readonly string[]).includes(key) &&
      typeof record[key] === 'string'
    ) {
      delete record[key];
    } else {
      scrubHostAuthJson(record[key]);
    }
  }
  return value;
}

export async function probeHostActor(
  fetchImpl: typeof fetch = fetch,
  env: EnvLike = defaultEnv(),
  timeoutMs: number = HOST_AUTH_PROBE_TIMEOUT_MS,
): Promise<HostWhoamiDto | null> {
  const base = getHostAuthBaseUrl(env);
  if (!base) return null;

  const controller = new AbortController();
  const timer = globalThis.setTimeout(() => controller.abort(), timeoutMs);
  let response: Response;
  try {
    response = await fetchImpl(`${base}/api/whoami`, {
      method: 'GET',
      credentials: 'include',
      headers: { Accept: 'application/json' },
      signal: controller.signal,
    });
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
  if (!response.ok) return null;

  let raw: unknown;
  try {
    raw = scrubHostAuthJson(await response.json());
  } catch {
    return null;
  }
  if (!raw || typeof raw !== 'object') return null;
  const record = raw as Record<string, unknown>;
  if (record.ok !== true) return null;
  if (typeof record.actorId !== 'string' || record.actorId.length === 0) return null;
  if (record.kind !== 'remote-account') return null;
  let email: string | null = null;
  if (record.email === null) email = null;
  else if (typeof record.email === 'string') email = record.email;
  else email = null;
  return {
    ok: true,
    actorId: record.actorId,
    kind: 'remote-account',
    email,
  };
}

export function isLocalAdminEnabled(): boolean {
  return import.meta.env.DEV === true;
}

export function isLocalAdminSession(): boolean {
  if (!isLocalAdminEnabled()) return false;
  if (typeof window === 'undefined') return false;
  if (window.localStorage.getItem(LOCAL_ADMIN_STORAGE_KEY) === 'true') return true;
  if (window.localStorage.getItem(LEGACY_LOCAL_ADMIN_STORAGE_KEY) === 'true') {
    window.localStorage.setItem(LOCAL_ADMIN_STORAGE_KEY, 'true');
    return true;
  }
  return false;
}

export function isTimedOut<T>(value: T | TimedOut): value is TimedOut {
  return value === TIMED_OUT;
}

export function raceWithTimeoutOrSymbol<T>(promise: PromiseLike<T>, ms: number): Promise<T | TimedOut> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<TimedOut>((resolve) => {
      window.setTimeout(() => resolve(TIMED_OUT), ms);
    }),
  ]);
}

export function raceWithTimeoutReject<T>(promise: PromiseLike<T>, ms: number, message: string): Promise<T> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<T>((_, reject) => {
      window.setTimeout(() => reject(new Error(message)), ms);
    }),
  ]);
}

