    { sourceSagaId },
    'Kopie konnte nicht erstellt werden',
  );
  if (!body.saga || typeof body.saga.sagaId !== 'string') {
    throw new Error('Kopie konnte nicht erstellt werden: ungültige Antwort');
  }
  return { sagaId: body.saga.sagaId };
}

