type EnvLike = {
  readonly VITE_SAGATREE_HOST_AUTH_URL?: string;
  readonly VITE_SAGATREE_HOST_LIBRARY?: string;
};

function defaultEnv(): EnvLike {
  try {
    return (import.meta as ImportMeta & { env?: EnvLike }).env ?? {};
  } catch {
    return {};
  }
}

export function isHostLibraryExplicitlyDisabled(env: EnvLike = defaultEnv()): boolean {
  const flag = env.VITE_SAGATREE_HOST_LIBRARY?.trim().toLowerCase();
  return flag === '0' || flag === 'false' || flag === 'off' || flag === 'no';
}

export function isHostLibraryEnabled(env: EnvLike = defaultEnv()): boolean {
  if (isHostLibraryExplicitlyDisabled(env)) return false;
  return getHostAuthBaseUrl(env) !== null;
}

async function hostMutateJson<T>(
  path: string,
  method: 'POST' | 'PATCH' | 'DELETE',
  unreachableMessage: string,
  payload?: unknown,
  env: EnvLike = defaultEnv(),
  fetchImpl: typeof fetch = fetch,
): Promise<T> {
  const base = getHostAuthBaseUrl(env);
  if (!base) throw new Error(unreachableMessage);
  let response: Response;
  try {
    response = await fetchImpl(`${base}${path}`, {
      method,
      credentials: 'include',
      headers: {
        Accept: 'application/json',
        ...(payload !== undefined ? { 'Content-Type': 'application/json' } : {}),
      },
      body: payload !== undefined ? JSON.stringify(payload) : undefined,
    });
  } catch {
    throw new Error(unreachableMessage);
  }
  if (!response.ok) {
    let detail = '';
    try {
      const body: unknown = await response.json();
      if (body && typeof body === 'object' && 'error' in body) {
        detail = String((body as { error: unknown }).error);
      }
    } catch {
      /* ignore */
    }
    throw new Error(detail || unreachableMessage);
  }
  if (response.status === 204) return undefined as T;
  return (await response.json()) as T;
}

export type HostNpcInstanceDto = {
  readonly id: string;
  readonly projectId: string;
  readonly sessionId: string | null;
  readonly definitionId: string;
  readonly displayName: string;
  readonly instanceKind: string;
  readonly sequenceNumber: number;
  readonly snapshot: Record<string, unknown>;
  readonly runtime: Record<string, unknown>;
  readonly createdBy?: string;
  readonly createdAt?: string;
  readonly updatedAt?: string;
};

export async function updateHostNpcInstanceRuntime(
  instanceId: string,
  runtime: unknown,
  env: EnvLike = defaultEnv(),
  fetchImpl: typeof fetch = fetch,
): Promise<HostNpcInstanceDto> {
  const body = await hostMutateJson<{ instance?: HostNpcInstanceDto }>(
    `/api/v1/library/npc-instances/${encodeURIComponent(instanceId)}/runtime`,
    'PATCH',
    'Host-NPC-Instanz-Status fehlgeschlagen',
    { runtime },
    env,
    fetchImpl,
  );
  if (!body.instance || typeof body.instance.id !== 'string') {
    throw new Error('Host-NPC-Instanz-Status: leere Antwort');
  }
  return body.instance;
}

export interface NpcCreatureInstanceRow {
  id: string;
  project_id: string;
  session_id: string | null;
  definition_id: string;
  display_name: string;
  instance_kind: string;
  sequence_number: number;
  snapshot: unknown;
  runtime: unknown;
  created_by?: string;
  created_at?: string;
  updated_at?: string;
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((entry): entry is string => typeof entry === 'string');
}

function parseRuntime(raw: unknown): NpcCreatureInstanceRuntime {
  const obj = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
  const temp =
    obj.temporaryControllerUserId === null
    || obj.temporaryControllerUserId === undefined
      ? null
      : typeof obj.temporaryControllerUserId === 'string'
        ? obj.temporaryControllerUserId
        : null;
  return {
    currentHp: typeof obj.currentHp === 'number' ? obj.currentHp : 0,
    conditions: asStringArray(obj.conditions),
    temporaryControllerUserId: temp && temp.trim() ? temp.trim() : null,
    encounterNotes: typeof obj.encounterNotes === 'string' ? obj.encounterNotes : '',
  };
}

export function toNpcCreatureInstance(row: NpcCreatureInstanceRow): NpcCreatureInstance {
  const kind: NpcCreatureInstanceKind =
    row.instance_kind === 'persistent' ? 'persistent' : 'generic';
  return {
    id: row.id,
    projectId: row.project_id,
    sessionId: row.session_id,
    definitionId: row.definition_id,
    displayName: row.display_name,
    instanceKind: kind,
    sequenceNumber: row.sequence_number,
    snapshot: parseSnapshot(row.snapshot),
    runtime: parseRuntime(row.runtime),
  };
}

export function toInstanceRuntimePayload(
  runtime: NpcCreatureInstanceRuntime,
): Record<string, unknown> {
  return {
    currentHp: runtime.currentHp,
    conditions: [...runtime.conditions],
    temporaryControllerUserId: runtime.temporaryControllerUserId,
    encounterNotes: runtime.encounterNotes,
  };
}

function mapHostInstanceDto(dto: HostNpcInstanceDto): NpcCreatureInstance {
  return toNpcCreatureInstance({
    id: dto.id,
    project_id: dto.projectId,
    session_id: dto.sessionId,
    definition_id: dto.definitionId,
    display_name: dto.displayName,
    instance_kind: dto.instanceKind,
    sequence_number: dto.sequenceNumber,
    snapshot: dto.snapshot,
    runtime: dto.runtime,
    created_by: dto.createdBy,
    created_at: dto.createdAt,
    updated_at: dto.updatedAt,
  });
}

export async function getAuthenticatedUserId(): Promise<string> {
  if (isHostLibraryEnabled()) {
    const actor = await probeHostActor();
    if (actor?.actorId) return actor.actorId;
    throw new Error('User not authenticated');
  }

  if (isLocalAdminSession()) {
    const sessionResult = await raceWithTimeoutOrSymbol(
      supabase.auth.getSession(),
      AUTH_SESSION_TIMEOUT_MS,
    );
    if (!isTimedOut(sessionResult) && sessionResult.data.session?.user) {
      return sessionResult.data.session.user.id;
    }
    return LOCAL_ADMIN_USER_ID;
  }

  const { data, error } = await raceWithTimeoutReject(
    supabase.auth.getUser(),
    SUPABASE_QUERY_TIMEOUT_MS,
    'Authentication request timed out',
  );
  if (error) throw error;
  if (data.user) return data.user.id;
  throw new Error('User not authenticated');
}

export type HostWhoamiDto = {
  readonly ok: true;
  readonly actorId: string;
  readonly kind: 'remote-account';
  readonly email: string | null;
};

function defaultEnv(): EnvLike {
  try {
    return (import.meta as ImportMeta & { env?: EnvLike }).env ?? {};
  } catch {
    return {};
  }
}

export function getHostAuthBaseUrl(env: EnvLike = defaultEnv()): string | null {
  const url = env.VITE_SAGATREE_HOST_AUTH_URL;
  if (typeof url !== 'string' || !url.trim()) return null;
  const trimmed = url.trim().replace(/\/$/, '');
  if (trimmed === 'same-origin' || trimmed === '.') {
    if (typeof window !== 'undefined' && typeof window.location?.origin === 'string') {
      return window.location.origin;
    }
    // Node / Vitest: enabled, relative `/api/...` paths.
    return '';
  }
  return trimmed;
}

export function scrubHostAuthJson<T>(value: T): T {
  if (!value || typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    for (const item of value) scrubHostAuthJson(item);
    return value;
  }
  const record = value as Record<string, unknown>;
  for (const key of Object.keys(record)) {
    if (
      (HOST_AUTH_SESSION_BEARER_KEYS as readonly string[]).includes(key) &&
      typeof record[key] === 'string'
    ) {
      delete record[key];
    } else {
      scrubHostAuthJson(record[key]);
    }
  }
  return value;
}

export async function probeHostActor(
  fetchImpl: typeof fetch = fetch,
  env: EnvLike = defaultEnv(),
  timeoutMs: number = HOST_AUTH_PROBE_TIMEOUT_MS,
): Promise<HostWhoamiDto | null> {
  const base = getHostAuthBaseUrl(env);
  if (!base) return null;

  const controller = new AbortController();
  const timer = globalThis.setTimeout(() => controller.abort(), timeoutMs);
  let response: Response;
  try {
    response = await fetchImpl(`${base}/api/whoami`, {
      method: 'GET',
      credentials: 'include',
      headers: { Accept: 'application/json' },
      signal: controller.signal,
    });
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
  if (!response.ok) return null;

  let raw: unknown;
  try {
    raw = scrubHostAuthJson(await response.json());
  } catch {
    return null;
  }
  if (!raw || typeof raw !== 'object') return null;
  const record = raw as Record<string, unknown>;
  if (record.ok !== true) return null;
  if (typeof record.actorId !== 'string' || record.actorId.length === 0) return null;
  if (record.kind !== 'remote-account') return null;
  let email: string | null = null;
  if (record.email === null) email = null;
  else if (typeof record.email === 'string') email = record.email;
  else email = null;
  return {
    ok: true,
    actorId: record.actorId,
    kind: 'remote-account',
    email,
  };
}

export function isLocalAdminEnabled(): boolean {
  return import.meta.env.DEV === true;
}

export function isLocalAdminSession(): boolean {
  if (!isLocalAdminEnabled()) return false;
  if (typeof window === 'undefined') return false;
  if (window.localStorage.getItem(LOCAL_ADMIN_STORAGE_KEY) === 'true') return true;
  if (window.localStorage.getItem(LEGACY_LOCAL_ADMIN_STORAGE_KEY) === 'true') {
    window.localStorage.setItem(LOCAL_ADMIN_STORAGE_KEY, 'true');
    return true;
  }
  return false;
}

export function isTimedOut<T>(value: T | TimedOut): value is TimedOut {
  return value === TIMED_OUT;
}

export function raceWithTimeoutOrSymbol<T>(promise: PromiseLike<T>, ms: number): Promise<T | TimedOut> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<TimedOut>((resolve) => {
      window.setTimeout(() => resolve(TIMED_OUT), ms);
    }),
  ]);
}

export function raceWithTimeoutReject<T>(promise: PromiseLike<T>, ms: number, message: string): Promise<T> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<T>((_, reject) => {
      window.setTimeout(() => reject(new Error(message)), ms);
    }),
  ]);
}

